import React, { useState } from "react";
import "./FormStyles.module.css";

function Form() {
  const [skills, setSkills] = useState([""]);
  const [projects, setProjects] = useState([
    { name: "", description: "", technology: "" },
  ]);
  const [education, setEducation] = useState([
    { name: "", place: "", marks: "", year: "" },
  ]);

  // Add skill
  const handleAddSkill = () => {
    setSkills([...skills, ""]);
  };

  const handleSkillChange = (index, value) => {
    const updatedSkills = [...skills];
    updatedSkills[index] = value;
    setSkills(updatedSkills);
  };

  const handleRemoveSkill = (index) => {
    const updatedSkills = skills.filter((_, i) => i !== index);
    setSkills(updatedSkills);
  };

  // Add project
  const handleAddProject = () => {
    setProjects([...projects, { name: "", description: "", technology: "" }]);
  };

  const handleProjectChange = (index, field, value) => {
    const updatedProjects = [...projects];
    updatedProjects[index][field] = value;
    setProjects(updatedProjects);
  };

  const handleRemoveProject = (index) => {
    const updatedProjects = projects.filter((_, i) => i !== index);
    setProjects(updatedProjects);
  };

  // Add education
  const handleAddEducation = () => {
    setEducation([
      ...education,
      { name: "", place: "", marks: "", year: "" },
    ]);
  };

  const handleEducationChange = (index, field, value) => {
    const updatedEducation = [...education];
    updatedEducation[index][field] = value;
    setEducation(updatedEducation);
  };

  const handleRemoveEducation = (index) => {
    const updatedEducation = education.filter((_, i) => i !== index);
    setEducation(updatedEducation);
  };

  // Handle form submission
  const handleSubmit = (event) => {
    event.preventDefault();
    console.log("Submitted Data:", {
      skills,
      projects,
      education,
    });
  };

  return (
    <div className="form-container">
      <form onSubmit={handleSubmit} className="form">
        <h2>PROFILE</h2>
        <input type="text" placeholder="Name" required />
        <input type="file" />
        <input type="text" placeholder="Role" required />
        <input type="date" required />

        <h2>ABOUT SECTION</h2>
        <textarea placeholder="Professional Summary" />

        {/* Skills Section */}
        <h2>Add Your Skills</h2>
        {skills.map((skill, index) => (
          <div key={index} className="input-group">
            <input
              type="text"
              value={skill}
              onChange={(e) => handleSkillChange(index, e.target.value)}
              placeholder={`Skill ${index + 1}`}
              className="input"
            />
            <button
              type="button"
              onClick={() => handleRemoveSkill(index)}
              className="remove"
            >
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={handleAddSkill}>
          Add Skill
        </button>

        {/* Projects Section */}
        <h2>Add Your Projects</h2>
        {projects.map((project, index) => (
          <div key={index} className="project-group">
            <input
              type="text"
              value={project.name}
              onChange={(e) =>
                handleProjectChange(index, "name", e.target.value)
              }
              placeholder={`Project Name ${index + 1}`}
              className="input"
            />
            <textarea
              value={project.description}
              onChange={(e) =>
                handleProjectChange(index, "description", e.target.value)
              }
              placeholder="Project Description"
              rows="3"
              className="textarea"
            ></textarea>
            <input
              type="text"
              value={project.technology}
              onChange={(e) =>
                handleProjectChange(index, "technology", e.target.value)
              }
              placeholder="Technology Used"
              className="input"
            />
            <button
              type="button"
              onClick={() => handleRemoveProject(index)}
              className="remove"
            >
              Remove Project
            </button>
          </div>
        ))}
        <button type="button" onClick={handleAddProject}>
          Add Project
        </button>

        {/* Education Section */}
        <h2>Add Your Education</h2>
        {education.map((edu, index) => (
          <div key={index} className="education-group">
            <input
              type="text"
              value={edu.name}
              onChange={(e) =>
                handleEducationChange(index, "name", e.target.value)
              }
              placeholder={`Institution Name ${index + 1}`}
              className="input"
            />
            <input
              type="text"
              value={edu.place}
              onChange={(e) =>
                handleEducationChange(index, "place", e.target.value)
              }
              placeholder="Place"
              className="input"
            />
            <input
              type="text"
              value={edu.marks}
              onChange={(e) =>
                handleEducationChange(index, "marks", e.target.value)
              }
              placeholder="Marks"
              className="input"
            />
            <input
              type="text"
              value={edu.year}
              onChange={(e) =>
                handleEducationChange(index, "year", e.target.value)
              }
              placeholder="Year of Completion"
              className="input"
            />
            <button
              type="button"
              onClick={() => handleRemoveEducation(index)}
              className="remove"
            >
              Remove Education
            </button>
          </div>
        ))}
        <button type="button" onClick={handleAddEducation}>
          Add Education
        </button>

        <button type="submit">Submit</button>
      </form>
    </div>
  );
}

export default Form;
